				SetAttributeField(manager.IsPartAttributeUsedByProduct(supplierPart, 3), manager.PartAttributeName3, WE_PartAttrib3TextBox, ref posY2);
				SetAttributeField(manager.IsSerialNumberUsedByProduct(supplierPart), "", WE_SerialNumberTextBox, ref posY2);

				var warehouse = inventoryLine.Warehouse;
